from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/output/result.xlsx', read_only=True, data_only=False)
for s in ['Task','Data']:
    ws=wb[s]
    print(f'\n{s} non-empty cells in rows 1-55, cols A:L:')
    for r in range(1, min(ws.max_row,55)+1):
        vals=[]
        for c in range(1, min(ws.max_column,12)+1):
            v=ws.cell(r,c).value
            if v is not None:
                vals.append(f'{get_column_letter(c)}={v!r}')
        if vals:
            print(f'  row {r}: '+', '.join(vals))
